{"source":{"sdkVersion":"0.2.0","entry":"visual.ts","files":{"kaleidoscope.ts":"import { Scene, Camera, Mesh, PlaneGeometry, MeshBasicNodeMaterial, OrthographicCamera } from 'three/webgpu';
import { pass, uniform, uv, vec2, vec4, float, atan, cos, sin, mix } from 'three/tsl';

// Reusable image effect: supply any underlying Three scene and its camera.
// It samples that scene's rendered image, including its alpha channel.
export function createKaleidoscope(inputScene: Scene, inputCamera: Camera, aspect: number) {
  const input = pass(inputScene, inputCamera);
  const image = input.getTextureNode();
  const segments = uniform(6), zoom = uniform(1.25), rotation = uniform(0);
  const twist = uniform(0.35), rings = uniform(1.2), blend = uniform(1);
  const prism = uniform(0.001), offsetX = uniform(0.015), offsetY = uniform(0.015);
  const sourceRadius = uniform(0.19);
  const sampleAngle = uniform(0);
  const screen = uv();
  const p = screen.sub(0.5).mul(vec2(aspect, 1));
  const radius = p.length().div(zoom);
  const sector = float(Math.PI * 2).div(segments);
  const angle = atan(p.y, p.x).add(rotation).add(radius.mul(twist));
  const folded = angle.div(sector).fract().sub(0.5).abs().mul(sector).add(sampleAngle);
  // Mirrored radial repetition keeps all samples within the source image.
  const distance = float(1).sub(radius.mul(rings).fract().mul(2).sub(1).abs()).mul(sourceRadius);
  const direction = vec2(cos(folded).div(aspect), sin(folded));
  const origin = vec2(offsetX.add(0.5), offsetY.add(0.5));
  const q = origin.add(direction.mul(distance));
  const center = image.sample(q);
  const red = image.sample(q.add(direction.mul(prism))).r;
  const blue = image.sample(q.sub(direction.mul(prism))).b;
  const processed = vec4(red, center.g, blue, center.a);
  const material = new MeshBasicNodeMaterial({ depthTest: false, depthWrite: false });
  material.fragmentNode = mix(image.sample(screen), processed, blend);
  const geometry = new PlaneGeometry(2, 2);
  const quad = new Mesh(geometry, material);
  quad.frustumCulled = false;
  const scene = new Scene();
  scene.add(quad);
  const camera = new OrthographicCamera(-1, 1, 1, -1, 0, 1);
  return {
    scene, camera,
    update(time: number, values: { segments: number; zoom: number; rotation: number; spin: number; twist: number; rings: number; blend: number; prism: number; offsetX: number; offsetY: number; drift: number; sourceRadius: number }) {
      segments.value = Math.round(values.segments);
      zoom.value = values.zoom;
      rotation.value = values.rotation + time * values.spin;
      twist.value = values.twist;
      rings.value = values.rings;
      blend.value = values.blend;
      prism.value = values.prism;
      sourceRadius.value = values.sourceRadius;
      offsetX.value = values.offsetX;
      offsetY.value = values.offsetY;
      sampleAngle.value = time * values.drift;
    },
    dispose() { geometry.dispose(); material.dispose(); input.dispose(); },
  };
}
","spiky-ball.ts":"import type { VisualContext } from '@lux/visual-sdk';
import { Scene, Mesh, IcosahedronGeometry, MeshPhysicalNodeMaterial, PerspectiveCamera, Color, AmbientLight, DirectionalLight } from 'three/webgpu';
import { uniform, vec3, positionLocal, mx_noise_float, mix, color, varying } from 'three/tsl';

// Original Prismatic Spikes geometry, material, lighting and animation.
const settings = {
  spikeHeight: 1.0,    // 0 = round; 2 = long thorns (zoom camera out)
  noiseScale: 3.6,    // Larger values create more, smaller spikes
  sharpness: 3.4,     // Larger values make narrower tips
  evolutionSpeed: 0.3,
  domainWarp: 0.48,   // Twists the noise field into organic shapes
  microDetail: 0.07,
  rotationSpeed: 0.13,
  metallic: 0.56,
  roughness: 0.29,
  iridescence: 0.85,
};

export async function createSpikyBall(context: VisualContext) {
    const clock = uniform(0);
    const intensity = uniform(0.55);
    const p = positionLocal.normalize();
    const drift = vec3(clock.mul(0.43), clock.mul(-0.31), clock.mul(0.22));
    const warp = mx_noise_float(p.mul(2.0).add(drift.mul(0.45))).mul(settings.domainWarp);
    const field = p.mul(settings.noiseScale).add(drift).add(warp);
    const noise = mx_noise_float(field).mul(0.8).add(0.44).clamp(0, 1);
    const spikes = noise.pow(settings.sharpness).mul(settings.spikeHeight).mul(intensity.mul(1.6).add(0.25));
    const pores = mx_noise_float(field.mul(3.1).sub(drift)).mul(settings.microDetail).mul(intensity);
    const radius = spikes.add(pores).add(0.85);
    const height = varying(spikes);

    const material = new MeshPhysicalNodeMaterial({
      metalness: settings.metallic, roughness: settings.roughness,
      clearcoat: 0.8, clearcoatRoughness: 0.22,
      iridescence: settings.iridescence, iridescenceIOR: 1.4,
      iridescenceThicknessRange: [120, 470], flatShading: true,
    });
    material.positionNode = p.mul(radius);
    material.colorNode = mix(color('#392565'), color('#21e6cb'), height.mul(1.8).clamp(0, 1));
    material.emissiveNode = mix(color('#120420'), color('#16b9b6'), height.mul(1.2).clamp(0, 1)).mul(0.13);
    const geometry = new IcosahedronGeometry(1, 32);
    const sphere = new Mesh(geometry, material);
    sphere.frustumCulled = false;
    const scene = new Scene();
    scene.background = new Color('#030510');
    scene.add(sphere);
    scene.add(new AmbientLight('#668ab4', 0.8));
    const key = new DirectionalLight('#bfefff', 4.4);
    key.position.set(3, 4, 4);
    scene.add(key);
    const rim = new DirectionalLight('#fc4fa4', 5.5);
    rim.position.set(-3, 1, -1);
    scene.add(rim);
    const fill = new DirectionalLight('#558bff', 2.0);
    fill.position.set(1, -3, 2);
    scene.add(fill);
    const camera = new PerspectiveCamera(36, context.settings.width / context.settings.height, 0.1, 30);
    camera.position.set(0, 0, 9);
    camera.lookAt(0, 0, 0);
    return {
      scene, camera,
      update(timeSeconds: number, spikeAmount: number) {
        intensity.value = spikeAmount;
        clock.value = timeSeconds * settings.evolutionSpeed * (0.5 + spikeAmount);
        sphere.rotation.y = timeSeconds * settings.rotationSpeed;
        sphere.rotation.x = Math.sin(timeSeconds * 0.17) * 0.16;
        sphere.rotation.z = 0.13;
      },
      reset(_seed: number) { clock.value = 0; sphere.rotation.set(0, 0, 0.13); },
      dispose() { geometry.dispose(); material.dispose(); },
    };
}
","visual.ts":"import { defineVisual } from '@lux/visual-sdk';
import { createSpikyBall } from './spiky-ball.ts';
import { createKaleidoscope } from './kaleidoscope.ts';

export default defineVisual({
  controls: {
    blend: { type: 'number', label: 'Kaleidoscope blend', default: 1, min: 0, max: 1, step: 0.01 },
    segments: { type: 'number', label: 'Mirror segments', default: 6, min: 2, max: 16, step: 1 },
    zoom: { type: 'number', label: 'Pattern zoom', default: 1.25, min: 0.4, max: 3, step: 0.01 },
    rings: { type: 'number', label: 'Radial repeats', default: 1.2, min: 0.4, max: 4, step: 0.01 },
    rotation: { type: 'number', label: 'Pattern angle', default: 0, min: -3.1416, max: 3.1416, step: 0.01, unit: 'rad' },
    spin: { type: 'number', label: 'Pattern spin', default: 0.08, min: -0.6, max: 0.6, step: 0.01, unit: 'rad/s' },
    twist: { type: 'number', label: 'Spiral twist', default: 0.35, min: -4, max: 4, step: 0.01 },
    prism: { type: 'number', label: 'Prism fringe', default: 0.001, min: 0, max: 0.025, step: 0.001 },
    sourceRadius: { type: 'number', label: 'Source sampling radius', default: 0.19, min: 0.05, max: 0.35, step: 0.005 },
    offsetX: { type: 'number', label: 'Source offset X', default: 0.015, min: -0.12, max: 0.12, step: 0.005 },
    offsetY: { type: 'number', label: 'Source offset Y', default: 0.015, min: -0.12, max: 0.12, step: 0.005 },
    drift: { type: 'number', label: 'Source drift', default: 0.05, min: -0.5, max: 0.5, step: 0.01 },
    intensity: { type: 'number', label: 'Ball spike amount', default: 0.67, min: 0, max: 1, step: 0.01 },
  },
  async create(context) {
    const ball = await createSpikyBall(context);
    const kaleidoscope = createKaleidoscope(ball.scene, ball.camera, context.settings.width / context.settings.height);
    return {
      update(frame) {
        ball.update(frame.timeSeconds, frame.controls.intensity);
        kaleidoscope.update(frame.timeSeconds, frame.controls);
      },
      render(target) { return context.renderer.render(kaleidoscope.scene, kaleidoscope.camera, target); },
      reset(seed) { ball.reset(seed); },
      dispose() { kaleidoscope.dispose(); ball.dispose(); },
    };
  },
});
